// Resolves the pending hero action id into input flags, then triggers a state change when its conditions hold.
void apply_hero_ground_material_response(void) {
    Hero *hero_state = &g_hero;
    Hero *g1;
    Hero *g2;
    Hero *g3;
    int saved_ground_sound_class = hero_state->ground_sound_class;
    int previous_ground_type = hero_state->ground_type;
    FastMemZero16(&hero_state->ground_type, 0x10);
    hero_state->ground_sound_class = saved_ground_sound_class;
    hero_state->ground_type = -1;
    hero_state->wading = 0;
    hero_state->unk308 = 0;
    if (previous_ground_type == -1)
        return;
    if (previous_ground_type == 2) {
        if (hero_state->frames_off_ground.s == 0 || hero_state->ground_distance < 0.3f) {
            hero_state->on_magnet_ground = 1;
            if (hero_state->vehicle_mode == 0) {
                Moby *item_slot_1_moby = hero_state->items[1].moby;
                if (item_slot_1_moby != 0 && item_slot_1_moby->oclass == 0xAD)
                    hero_state->unk308 = 1;
            }
        }
    }
    if (previous_ground_type == 0xD) {
        Hero *gx = &g_hero;
        gx->selector_13 = 1;
    }
    if (previous_ground_type == 1) {
        Hero *gx = &g_hero;
        gx->selector_1 = 1;
    }
    if (previous_ground_type == 8) {
        Hero *gx = &g_hero;
        gx->on_slip_ground = 1;
    }
    if (previous_ground_type == 9) {
        Hero *gx = &g_hero;
        gx->unk12EE = 1;
    }
    if (previous_ground_type == 0xC) {
        Hero *gx = &g_hero;
        gx->on_slip_ground = 1;
    }
    g1 = &g_hero;
    if (g1->selector_1 != 0) {
        if (g1->grounded_frames != 0 && g1->vehicle_mode == 1 && g1->state.current != 0x7D) {
            HeroL06_TrySetMoveState(0x7D, 1);
            return;
        }
        g2 = &g_hero;
        if (g2->selector_1 != 0) {
            if (g2->grounded_frames != 0) {
                if (g2->state.current != 0x3C || g2->past_jump_apex != 0) {
                    exit_hero_vehicle_mode_if_mode_three();
                    if (g2->health.hp != 0) {
                        HeroL06_TrySetMoveState(0x3C, 1);
                    } else {
                        HeroL06_TrySetMoveState(HERO_STATE_DEATH_DESCENT, 1);
                    }
                    return;
                }
            }
        }
    }
    g3 = &g_hero;
    if (g3->selector_13 == 0)
        return;
    if (g3->state.current == HERO_STATE_SINK)
        return;
    if (!(absolute_float(g3->water_surface_z - (g3->motion.pos.f[2] + 0.25f)) < 1.0f))
        return;
    if (!(0.0f < g3->water_surface_z - g3->motion.pos.f[2]))
        return;
    if (!(g3->motion.displacement.f[2] < 0.0f))
        return;
    exit_hero_vehicle_mode_if_mode_three();
    HeroL06_TrySetMoveState(HERO_STATE_SINK, 1);
}
