                        FastVecScale(vec[5], vec[5], 0.5f);
                        g_hero.motion.move_yaw = mid;
                        turn_to(0, g_frame_scale_sq * 0.04f, g_frame_scale_sq * 0.2f, g_frame_time * 6.2831855f);
